using Microsoft.EntityFrameworkCore;
using WelcomeEmail.WebApi;

var builder = WebApplication.CreateBuilder(args);

var connectionString = builder.Configuration.GetConnectionString("WelcomeEmailDatabase")
    ?? "Host=localhost;Port=5435;Database=welcome_email_sample;Username=postgres;Password=postgres";

builder.Services.AddDbContext<SampleDbContext>(options => options
    .UseNpgsql(connectionString)
    .UseNpgsqlNotifications());

var app = builder.Build();

// Applies any pending migrations on startup, which is what actually creates the INSERT
// trigger/trigger function generated by PgNotify.Migrations (pulled in transitively through
// PgNotify.Writer) - see Migrations/ for the checked-in migration produced by
// `dotnet ef migrations add InitialCreate`. This app never listens for its own notifications;
// see ../WelcomeEmail.Mailer for the separate process that turns them into emails.
using (var scope = app.Services.CreateScope())
{
    await scope.ServiceProvider.GetRequiredService<SampleDbContext>().Database.MigrateAsync();
}

app.MapMemberEndpoints();

app.Run();

public partial class Program;
